parameters.jsonBody:
={
  "messages": {
    "authentication": { "producttoken": "{{$credentials.cmProductToken}}" },
    "msg": [{
      "from": "={{ $json.bedrijfsnaam }}",
      "to": [{ "number": "={{ $json.owner_e164 }}" }],
      "body": { "content": "{{ $json.owner_voornaam }}, vandaag bij {{ $json.bedrijfsnaam }}:\n{{ $json.calls_taken }} calls door AI, {{ $json.missed_recovered }} gemist teruggewonnen, {{ $json.bookings }} boekingen, {{ $json.reviews }} reviews.\nDashboard: https://klantkraan.nl/r/{{ $json.slug }}" },
      "reference": "daily-{{ $json.client_id }}-{{ $now.toFormat('yyyy-LL-dd') }}"
    }]
  }
}
